{"code": "module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output reg valid_out,
    output reg dout
);

    reg [3:0] data;
    reg [1:0] cnt;

    // dout: combinational logic operation. MSB of data register.
    assign dout = data[3];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 2'b00;
            valid_out <= 0;
            data <= 4'b0000;
        end else begin
            if (cnt == 2'b11) begin
                data <= d; // Update data register with parallel input
                cnt <= 2'b00; // Reset counter
                valid_out <= 1; // Set valid signal
            end else begin
                cnt <= cnt + 1; // Increment counter
                valid_out <= 0; // Clear valid signal
                data <= {data[2:0], data[3]}; // Shift data left
            end
        end
    end
endmodule
", "description": "This module implements a parallel-to-serial converter that takes a 4-bit parallel input and outputs it serially, one bit per clock cycle. The valid_out signal indicates when the output is valid."}

