    reg [1:0] cnt;

    assign dout = data[3]; // dout is the MSB of data

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 2'b00;
            valid_out <= 0;
            data <= 4'b0000;
        end else begin
            if (cnt == 2'b11) begin
